/**
 * Avatar.Group: a row of overlapping Avatars with a "+N" chip when `max` cuts the set.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/avatar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, SlotOutlet, SlotTemplate, classes, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/avatar.module.css'

/** Avatar.Group: a row of overlapping Avatars with a "+N" chip when `max` cuts the set: the inputs it takes, by the React member's prop names. */
export interface AvatarGroupProps {
  /**
   * Maximum number drawn; the rest become "+N", and omitting it draws all.
   */
  max?: number
  /**
   * The group’s accessible name, such as "Assignees" rather than "Avatars".
   */
  label: string
}

/** Avatar.Group: a row of overlapping Avatars with a "+N" chip when `max` cuts the set. */
@Component({
  selector: 'pm-avatar-group',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<div
[attr.class]="e1()"
role="group"
[attr.aria-label]="e2()"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" [pmSlotTake]="e3()" />
@if (e4()) {<!-- surplus -->
<span
[attr.class]="e5()"
[attr.data-size]="e6()"
>{{ e7() }}</span>}</div>`,
})
export class AvatarGroup {
  /**
   * Maximum number drawn; the rest become "+N", and omitting it draws all.
   */
  readonly max = input<AvatarGroupProps['max']>(undefined)
  /**
   * The group’s accessible name, such as "Assignees" rather than "Avatars".
   */
  readonly label = input.required<AvatarGroupProps['label']>()
  protected readonly $ = useMember({
    events: [],
    props: { max: () => this.max(), label: () => this.label() },
  })
  protected readonly $p = this.$.props

  constructor() {
    this.$.pass('default', (child) => ({ label: child.label ?? child.name }))
  }

  protected e1() {
    return styles.group
  }

  protected e2() {
    return this.$p.label
  }

  protected e3() {
    return this.$p.max
  }

  protected e4() {
    return this.$p.max !== undefined && this.$.slotted('default').count > this.$p.max
  }

  protected e5() {
    if (!(this.$p.max !== undefined && this.$.slotted('default').count > this.$p.max))
      return undefined as never
    return classes(styles.avatar, styles.surplus)
  }

  protected e6() {
    if (!(this.$p.max !== undefined && this.$.slotted('default').count > this.$p.max))
      return undefined as never
    return this.$.slotted('default').props.size ?? 'md'
  }

  protected e7() {
    if (!(this.$p.max !== undefined && this.$.slotted('default').count > this.$p.max))
      return undefined as never
    return `+${this.$.slotted('default').count - this.$p.max}`
  }
}
